/******************************************************************************************
 * bp_audio.h -- 100% procedurally synthesised audio.
 *
 * Why no .ogg / .wav assets?
 *   1. A Web/WASM build pays for every byte twice: download size *and* decode time. An
 *      entire weapon bank synthesised at boot costs ~400 KB of RAM and 0 KB of download.
 *   2. There is no licensing risk in a shipped commercial build -- every sample here is
 *      generated by our own DSP code.
 *   3. Sound design becomes data: change `shotgun.body_freq` and the gun sounds different,
 *      no DAW round-trip.
 *
 * Architecture:
 *   bp_sfx_init()      synthesises every one-shot into a mono float scratch buffer, then
 *                      hands it to raylib as a Sound (LoadSoundFromSample).
 *   bp_audio_play()    allocates a voice, applies randomised pitch + stereo pan from the
 *                      listener-relative position, and starts it.
 *   bp_audio_update()  advances per-sound 3D attenuation and refreshes the music loop.
 ******************************************************************************************/
#ifndef BP_AUDIO_H
#define BP_AUDIO_H

#include "bp_common.h"

typedef enum {
    SFX_NONE = -1,

    /* weapons */
    SFX_PISTOL_FIRE, SFX_PISTOL_DRY,
    SFX_SHOTGUN_FIRE, SFX_SHOTGUN_PUMP,
    SFX_SMG_FIRE,
    SFX_RAIL_CHARGE, SFX_RAIL_FIRE,
    SFX_ROCKET_FIRE,
    SFX_RELOAD_OUT, SFX_RELOAD_IN, SFX_RELOAD_DONE,
    SFX_WEAPON_SWAP,

    /* impacts */
    SFX_HIT_FLESH, SFX_HIT_ARMOR, SFX_HIT_WALL, SFX_RICOCHET,
    SFX_EXPLOSION, SFX_EXPLOSION_DISTANT,

    /* enemies */
    SFX_GRUNT_SIGHT, SFX_GRUNT_PAIN, SFX_GRUNT_DIE,
    SFX_HOUND_SIGHT, SFX_HOUND_ATTACK, SFX_HOUND_DIE,
    SFX_TURRET_FIRE, SFX_TURRET_DIE,
    SFX_BRUTE_ROAR, SFX_BRUTE_DIE,

    /* player */
    SFX_JUMP, SFX_LAND, SFX_FOOTSTEP, SFX_HURT, SFX_HEAL, SFX_ARMOR, SFX_AMMO_PICKUP,
    SFX_LOW_HEALTH,

    /* world / ui */
    SFX_UI_MOVE, SFX_UI_SELECT, SFX_UI_BACK,
    SFX_WAVE_START, SFX_WAVE_CLEAR, SFX_DOOR, SFX_SECRET,

    SFX_COUNT
} bp_sfx_id;

typedef struct {
    Sound  sound;
    bool   valid;
    float  base_volume;
    float  pitch_min;      /* randomisation range, applied per voice */
    float  pitch_max;
    float  falloff;        /* world units at which the sound is silent */
    float  cooldown;       /* minimum seconds between two triggers of the same id */
    double last_played;
} bp_sfx_def;

typedef struct {
    bool  initialised;
    float master_volume;
    float sfx_volume;
    float music_volume;

    bp_sfx_def sfx[SFX_COUNT];

    /* dynamic music */
    Music music_calm;
    Music music_combat;
    Music music_boss;
    bool  music_valid[3];
    int   music_current;      /* -1 = silence, 0 calm, 1 combat, 2 boss */
    float music_fade;         /* crossfade progress 0..1 */
    float intensity;          /* smoothed 0..1 "how much fighting is happening" */

    int   active_voices;
    int   dropped_voices;     /* telemetry: how often we hit the voice cap */
} bp_audio_sys;

extern bp_audio_sys g_audio;

void bp_audio_init(void);
void bp_audio_shutdown(void);
void bp_audio_update(float dt);

/* Play at the listener (UI, weapon fire). */
void bp_audio_play(bp_sfx_id id, float volumeScale);

/* Play in the world: volume falls off with distance to `listener`, panned by bearing. */
void bp_audio_play_at(bp_sfx_id id, Vector3 position, Vector3 listenerPos,
                      Vector3 listenerForward, float volumeScale);

/* Randomised variant, used for footsteps / ambient so repetition is not audible. */
void bp_audio_play_variant(bp_sfx_id id, Vector3 position, Vector3 listenerPos,
                           Vector3 listenerForward, float volumeScale, float pitchJitter);

void bp_audio_set_intensity(float target01, float dt);
void bp_audio_set_volumes(float master, float sfx, float music);
const char *bp_audio_sfx_name(bp_sfx_id id);

#endif /* BP_AUDIO_H */
